INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d609b09d-b5d1-5321-b689-726603f31bcb', 'Finland Government Resolution on State-Ownership Policy: Making the balance', 'Government Resolution on State-Ownership Policy: Making the balance sheet work – Growth-generating ownership policy 2016', 'The Government Resolution on State-Ownership Policy in Finland aims to make state-owned companies more efficient and beneficial for the national economy. It emphasizes the need for active development of state ownership based on overall benefit, value creation, and efficient resource allocation. The policy sets goals for state ownership as a tool for societal renewal, encouraging investment in the platform economy and supporting long-term employment objectives. Changes in ownership strategy include releasing capital for new ventures, establishing a business development company, and promoting corporate social responsibility. The policy highlights the importance of maximizing financial and social benefits from state-owned assets.', 'The Government Resolution on State-Ownership Policy in Finland aims to make state-owned companies more efficient and beneficial for the national economy. It emphasizes the need for active development of state ownership based on overall benefit, value creation, and efficient resource allocation. The policy sets goals for state ownership as a tool for societal renewal, encouraging investment in the platform economy and supporting long-term employment objectives. Changes in ownership strategy include releasing capital for new ventures, establishing a business development company, and promoting corporate social responsibility. The policy highlights the importance of maximizing financial and social benefits from state-owned assets.', 'The Government Resolution on State-Ownership Policy in Finland aims to make state-owned companies more efficient and beneficial for the national economy. It emphasizes the need for active development of state ownership based on overall benefit, value creation, and efficient resource allocation. The policy sets goals for state ownership as a tool for societal renewal, encouraging investment in the platform economy and supporting long-term employment objectives. Changes in ownership strategy include releasing capital for new ventures, establishing a business development company, and promoting corporate social responsibility. The policy highlights the importance of maximizing financial and social benefits from state-owned assets.', 'Finland', 'climate', 'in_force', '2016-01-01'::date, 'Finland', 'https://www.carrotsandsticks.org/policies/57_28', ARRAY['sdg8', 'other sustainability policy', 'mandatory', 'mandatory_regulations', 'sdg15', 'finland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ff951294-7f5c-5d7b-8371-e1a9887ca8d1', 'Finland Disclosure of Payments to the Authorities by Mining', 'Act on the Disclosure of Payments to the Authorities by Mining and Harvesting Companies', 'This Act lays down the obligation for a company engaged in the extractive industry or the harvesting of virgin forests to disclose to the authorities, in the annual report, payments made to it in the States in which it operates.', 'This Act lays down the obligation for a company engaged in the extractive industry or the harvesting of virgin forests to disclose to the authorities, in the annual report, payments made to it in the States in which it operates.', 'This Act lays down the obligation for a company engaged in the extractive industry or the harvesting of virgin forests to disclose to the authorities, in the annual report, payments made to it in the States in which it operates.', 'Finland', 'climate', 'in_force', '2015-01-01'::date, 'Finland', 'https://www.carrotsandsticks.org/policies/57_1', ARRAY['sdg9', 'regulations', 'mandatory', 'disclosure', 'sdg15', 'finland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('440efc63-94cd-5576-b1f8-e0e41b93f56f', 'Environmental Impact Assessment Procedure for Mining Projects in Finland', 'Environmental Impact Assessment Procedure for Mining Projects in Finland', 'The purpose of the Environmental Impact Assessment (EIA) procedure is to generate information on the environmental impacts of a project, facilitate the consideration of environmental issues in planning and decision-making processes, and give the public and other stakeholders opportunities to participate in and affect these processes.', 'The purpose of the Environmental Impact Assessment (EIA) procedure is to generate information on the environmental impacts of a project, facilitate the consideration of environmental issues in planning and decision-making processes, and give the public and other stakeholders opportunities to participate in and affect these processes.', 'The purpose of the Environmental Impact Assessment (EIA) procedure is to generate information on the environmental impacts of a project, facilitate the consideration of environmental issues in planning and decision-making processes, and give the public and other stakeholders opportunities to participate in and affect these processes.', 'Finland', 'climate', 'in_force', '2015-01-01'::date, 'Finland', 'https://www.carrotsandsticks.org/policies/57_15', ARRAY['sdg8', 'other sustainability policy', 'regulations', 'mandatory', 'sdg15', 'finland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('b518621a-6de3-5b76-9cf9-4ad8b2da8bfb', 'Finland Finnish Corporate Governance Code', 'Finnish Corporate Governance Code 2015', 'Promoting openness, transparency, and comparability, as well as good corporate governance, in a manner that enhances the competitiveness and success of Finnish listed companies have been among the most important objectives of the reform of the Corporate Governance Code.', 'Promoting openness, transparency, and comparability, as well as good corporate governance, in a manner that enhances the competitiveness and success of Finnish listed companies have been among the most important objectives of the reform of the Corporate Governance Code.', 'Promoting openness, transparency, and comparability, as well as good corporate governance, in a manner that enhances the competitiveness and success of Finnish listed companies have been among the most important objectives of the reform of the Corporate Governance Code.', 'Finland', 'climate', 'in_force', '2015-01-01'::date, 'Finland', 'https://www.carrotsandsticks.org/policies/57_3', ARRAY['mandatory', 'sdg16', 'mandatory_regulations', 'disclosure', 'finland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('22dc0419-5b41-5769-b5e0-c781cfb8284f', 'Finland Environmental Protection Act (; amendments up to included)', 'Environmental Protection Act (527/2014; amendments up to 49/2019 included)', 'The purpose of this Act is to: 1) prevent the pollution of the environment and any risk of this, prevent and reduce emissions, eliminate adverse impacts caused by pollution and prevent environmental damage; 2) safeguard a healthy, pleasant, ecologically sustainable and biologically diverse environment, support sustainable development and combat climate change; 3) promote sustainable use of natural resources, reduce the amount and harmfulness of waste, and prevent adverse impacts caused by waste; 4) make the assessment of activities causing pollution and the consideration of the impacts as a whole more effective; 5) improve the opportunities of citizens to affect decision-making concerning the environment.', 'The purpose of this Act is to: 1) prevent the pollution of the environment and any risk of this, prevent and reduce emissions, eliminate adverse impacts caused by pollution and prevent environmental damage; 2) safeguard a healthy, pleasant, ecologically sustainable and biologically diverse environment, support sustainable development and combat climate change; 3) promote sustainable use of natural resources, reduce the amount and harmfulness of waste, and prevent adverse impacts caused by waste; 4) make the assessment of activities causing pollution and the consideration of the impacts as a whole more effective; 5) improve the opportunities of citizens to affect decision-making concerning the environment.', 'The purpose of this Act is to: 1) prevent the pollution of the environment and any risk of this, prevent and reduce emissions, eliminate adverse impacts caused by pollution and prevent environmental damage; 2) safeguard a healthy, pleasant, ecologically sustainable and biologically diverse environment, support sustainable development and combat climate change; 3) promote sustainable use of natural resources, reduce the amount and harmfulness of waste, and prevent adverse impacts caused by waste; 4) make the assessment of activities causing pollution and the consideration of the impacts as a whole more effective; 5) improve the opportunities of citizens to affect decision-making concerning the environment.', 'Finland', 'climate', 'in_force', '2014-01-01'::date, 'Finland', 'https://www.carrotsandsticks.org/policies/57_16', ARRAY['sdg3', 'sdg13', 'other sustainability policy', 'regulations', 'mandatory', 'sdg12', 'finland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5239e218-ee4b-503c-9135-f139b9570cad', 'Finland Non-discrimination Act ()', 'Non-discrimination Act (1325/2014)', 'The purpose of this Act is to promote equality and prevent discrimination as well as to enhance the protection provided by law to those who have been discriminated against.', 'The purpose of this Act is to promote equality and prevent discrimination as well as to enhance the protection provided by law to those who have been discriminated against.', 'The purpose of this Act is to promote equality and prevent discrimination as well as to enhance the protection provided by law to those who have been discriminated against.', 'Finland', 'social', 'in_force', '2014-01-01'::date, 'Finland', 'https://www.carrotsandsticks.org/policies/57_2', ARRAY['other sustainability policy', 'sdg10', 'regulations', 'mandatory', 'sdg16', 'finland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7b61e6e9-62ee-5d91-bef5-34724ecbaa2e', 'Finland Waste Act (; amendments up to included)', 'Waste Act (646/2011; amendments up to 528/2014 included)', 'The purpose of this Act is to prevent the hazard and harm to human health and the environment posed by waste and waste management, to reduce the amount and harmfulness of waste, to promote the sustainable use of natural resources, to ensure functioning waste management, and to prevent littering.', 'The purpose of this Act is to prevent the hazard and harm to human health and the environment posed by waste and waste management, to reduce the amount and harmfulness of waste, to promote the sustainable use of natural resources, to ensure functioning waste management, and to prevent littering.', 'The purpose of this Act is to prevent the hazard and harm to human health and the environment posed by waste and waste management, to reduce the amount and harmfulness of waste, to promote the sustainable use of natural resources, to ensure functioning waste management, and to prevent littering.', 'Finland', 'climate', 'in_force', '2014-01-01'::date, 'Finland', 'https://www.carrotsandsticks.org/policies/57_26', ARRAY['sdg2', 'sdg3', 'regulations', 'sdg11', 'mandatory', 'sdg12', 'disclosure', 'sdg15', 'finland']::text[]) ON CONFLICT (id) DO NOTHING;
