INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3c3b3320-c671-5252-9569-d52973f364ab', 'Finland Decree of the Ministry of Employment and the', 'Decree of the Ministry of Employment and the Economy on the monitoring and reporting of greenhouse gas emissions in the emissions trading period 2013-2020', 'This Regulation provides for the national implementation of Commission Regulation 2012/601/EU on the monitoring and reporting of greenhouse gas emissions pursuant to Article 14 (1) of Directive 2003/87 / EC of the European Parliament and of the Council, hereinafter " the Emissions Trading Regulation ".
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('cc75831f-86ee-5b0c-8221-e77bfe3fccf5', 'Finland Securities Markets Act', 'Securities Markets Act', 'This Act shall govern the issuance of securities to the public, the disclosure obligation on the securi- ties markets, takeover bids, prevention of market abuse and supervision of the securities market. This Act shall also apply to activities taking place outside Finland as provided below.', 'This Act shall govern the issuance of securities to the public, the disclosure obligation on the securi- ties markets, takeover bids, prevention of market abuse and supervision of the securities market. This Act shall also apply to activities taking place outside Finland as provided below.', 'This Act shall govern the issuance of securities to the public, the disclosure obligation on the securi- ties markets, takeover bids, prevention of market abuse and supervision of the securities market. This Act shall also apply to activities taking place outside Finland as provided below.', 'Finland', 'nature', 'in_force', '2012-01-01'::date, 'Finland', 'https://www.carrotsandsticks.org/policies/57_21', ARRAY['regulations', 'mandatory', 'disclosure', 'sdg15', 'finland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('cb1da283-c7ba-54c9-a2b7-d2b5fbae1f45', 'Finland Government decision-in-principle on social responsibility', 'Government decision-in-principle on social responsibility', 'The aim of this decision-in-principle is to make Finnish companies and the administration a leader in matters of corporate social responsibility.', 'The aim of this decision-in-principle is to make Finnish companies and the administration a leader in matters of corporate social responsibility.', 'The aim of this decision-in-principle is to make Finnish companies and the administration a leader in matters of corporate social responsibility.', 'Finland', 'climate', 'in_force', '2012-01-01'::date, 'Finland', 'https://www.carrotsandsticks.org/policies/57_7', ARRAY['guidance_frameworks', 'sdg8', 'sdg7', 'sdg11', 'sdg17', 'voluntary', 'sdg16', 'sdg12', 'disclosure', 'finland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('297e5517-c96a-53f9-8094-cba55c62de88', 'Finland Emissions Trading Act', 'Emissions Trading Act', 'The purpose of this law is to promote the reduction of greenhouse gas emissions in a cost-effective and economical manner.', 'The purpose of this law is to promote the reduction of greenhouse gas emissions in a cost-effective and economical manner.', 'The purpose of this law is to promote the reduction of greenhouse gas emissions in a cost-effective and economical manner.', 'Finland', 'climate', 'in_force', '2011-01-01'::date, 'Finland', 'https://www.carrotsandsticks.org/policies/57_25', ARRAY['sdg13', 'regulations', 'sdg7', 'mandatory', 'sdg12', 'disclosure', 'sdg9', 'finland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('62d570b2-0323-554b-91d8-89dc392b4609', 'Finland Government Resolution on State Ownership Policy', 'Government Resolution on State Ownership Policy 2011', 'The Government Resolution on State Ownership Policy 2011 in Finland aims to develop and reinforce state ownership policy and steering to increase shareholder value of state-owned companies sustainably. It supports growth, employment, and socially sustainable development while safeguarding employees. The policy focuses on consolidating domestic ownership in companies of national importance, with open, predictable, and consistent practices. Solidium plays a key role in ensuring long-term ownership and value increase. The resolution outlines principles for state shareholders and is intended for authorities implementing the policy, not companies.', 'The Government Resolution on State Ownership Policy 2011 in Finland aims to develop and reinforce state ownership policy and steering to increase shareholder value of state-owned companies sustainably. It supports growth, employment, and socially sustainable development while safeguarding employees. The policy focuses on consolidating domestic ownership in companies of national importance, with open, predictable, and consistent practices. Solidium plays a key role in ensuring long-term ownership and value increase. The resolution outlines principles for state shareholders and is intended for authorities implementing the policy, not companies.', 'The Government Resolution on State Ownership Policy 2011 in Finland aims to develop and reinforce state ownership policy and steering to increase shareholder value of state-owned companies sustainably. It supports growth, employment, and socially sustainable development while safeguarding employees. The policy focuses on consolidating domestic ownership in companies of national importance, with open, predictable, and consistent practices. Solidium plays a key role in ensuring long-term ownership and value increase. The resolution outlines principles for state shareholders and is intended for authorities implementing the policy, not companies.', 'Finland', 'climate', 'in_force', '2011-01-01'::date, 'Finland', 'https://www.carrotsandsticks.org/policies/57_4', ARRAY['sdg8', 'other sustainability policy', 'mandatory', 'mandatory_regulations', 'sdg15', 'finland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2bfe0acc-3e64-524b-a3b5-ee426ad89f2d', 'Finland Finnish Corporate Governance Code', 'Finnish Corporate Governance Code 2010', 'The aim of the Code is that Finnish listed companies apply corporate governance practices that are of a high international standard. The Code will harmonise the practices of listed companies as well as the information given to shareholders and other investors. It will also improve the transparency of administrative bodies, management remuneration and remuneration policies. The Code also provides an overall picture of the central principles of the corporate governance system of Finnish listed companies. Good corporate governance will enhance the success of Finnish listed companies.', 'The aim of the Code is that Finnish listed companies apply corporate governance practices that are of a high international standard. The Code will harmonise the practices of listed companies as well as the information given to shareholders and other investors. It will also improve the transparency of administrative bodies, management remuneration and remuneration policies. The Code also provides an overall picture of the central principles of the corporate governance system of Finnish listed companies. Good corporate governance will enhance the success of Finnish listed companies.', 'The aim of the Code is that Finnish listed companies apply corporate governance practices that are of a high international standard. The Code will harmonise the practices of listed companies as well as the information given to shareholders and other investors. It will also improve the transparency of administrative bodies, management remuneration and remuneration policies. The Code also provides an overall picture of the central principles of the corporate governance system of Finnish listed companies. Good corporate governance will enhance the success of Finnish listed companies.', 'Finland', 'governance', 'in_force', '2010-01-01'::date, 'Finland', 'https://www.carrotsandsticks.org/policies/57_12', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'finland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e8165d79-aa72-5c3c-b2d6-b13443704d89', 'Finland Finnish Corporate Governance Code', 'Finnish Corporate Governance Code 2008', 'The Corporate Governance Recommendation for Listed Companies issued in 2003 has been seen to work well and to meet high standards internationally. All listed companies and many companies not listed on the Helsinki exchange apply it to their operations. The recommendation has materially improved the corporate governance practices of Finnish companies. However, new regulation and international developments have created a need to update the recommendation. In addition, it has become necessary to improve international investors’ access to information about the Finnish corporate governance system as a whole and, above all, the rights of shareholders. The Code will replace the Corporate Governance Recommendation for Listed Companies issued in 2003.', 'The Corporate Governance Recommendation for Listed Companies issued in 2003 has been seen to work well and to meet high standards internationally. All listed companies and many companies not listed on the Helsinki exchange apply it to their operations. The recommendation has materially improved the corporate governance practices of Finnish companies. However, new regulation and international developments have created a need to update the recommendation. In addition, it has become necessary to improve international investors’ access to information about the Finnish corporate governance system as a whole and, above all, the rights of shareholders. The Code will replace the Corporate Governance Recommendation for Listed Companies issued in 2003.', 'The Corporate Governance Recommendation for Listed Companies issued in 2003 has been seen to work well and to meet high standards internationally. All listed companies and many companies not listed on the Helsinki exchange apply it to their operations. The recommendation has materially improved the corporate governance practices of Finnish companies. However, new regulation and international developments have created a need to update the recommendation. In addition, it has become necessary to improve international investors’ access to information about the Finnish corporate governance system as a whole and, above all, the rights of shareholders. The Code will replace the Corporate Governance Recommendation for Listed Companies issued in 2003.', 'Finland', 'governance', 'in_force', '2008-01-01'::date, 'Finland', 'https://www.carrotsandsticks.org/policies/57_11', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'finland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4d51af79-8484-5488-ac8f-f141f41b6b48', 'Finland Finnish Corporate Governance Code (Preliminary translation)', 'Finnish Corporate Governance Code (Preliminary translation) 2008', 'The Corporate Governance Recommendation for Listed Companies issued in 2003 has been regarded as well-functioning and of an internationally high standard. All listed companies and many unlisted companies apply it to their operations. The recommendation has essentially improved the corporate governance systems of Finnish companies. New regulations and international development have, however, given rise to the need to update the recommendation. In addition, it has become necessary to improve international investors’ access to information about the Finnish corporate governance system. as a whole and, above all, the rights of shareholders.', 'The Corporate Governance Recommendation for Listed Companies issued in 2003 has been regarded as well-functioning and of an internationally high standard. All listed companies and many unlisted companies apply it to their operations. The recommendation has essentially improved the corporate governance systems of Finnish companies. New regulations and international development have, however, given rise to the need to update the recommendation. In addition, it has become necessary to improve international investors’ access to information about the Finnish corporate governance system. as a whole and, above all, the rights of shareholders.', 'The Corporate Governance Recommendation for Listed Companies issued in 2003 has been regarded as well-functioning and of an internationally high standard. All listed companies and many unlisted companies apply it to their operations. The recommendation has essentially improved the corporate governance systems of Finnish companies. New regulations and international development have, however, given rise to the need to update the recommendation. In addition, it has become necessary to improve international investors’ access to information about the Finnish corporate governance system. as a whole and, above all, the rights of shareholders.', 'Finland', 'governance', 'in_force', '2008-01-01'::date, 'Finland', 'https://www.carrotsandsticks.org/policies/57_13', ARRAY['regulations', 'mandatory', 'sdg16', 'disclosure', 'finland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('bdcb80b7-e605-5962-883c-68eb7e299d50', 'Finland Government Decree concerning the recovery of certain wastes', 'Government Decree 591/2006 concerning the recovery of certain wastes in earth construction', 'The objective of this Decree is to promote the recovery of wastes by determining the preconditions as the result of which, if met, no environmental permit in accordance with the Environmental Protection Act (86/2000) will be needed for use in earth construction from waste referred to in this Decree.', 'The objective of this Decree is to promote the recovery of wastes by determining the preconditions as the result of which, if met, no environmental permit in accordance with the Environmental Protection Act (86/2000) will be needed for use in earth construction from waste referred to in this Decree.', 'The objective of this Decree is to promote the recovery of wastes by determining the preconditions as the result of which, if met, no environmental permit in accordance with the Environmental Protection Act (86/2000) will be needed for use in earth construction from waste referred to in this Decree.', 'Finland', 'climate', 'in_force', '2006-01-01'::date, 'Finland', 'https://www.carrotsandsticks.org/policies/57_18', ARRAY['other sustainability policy', 'regulations', 'mandatory', 'sdg12', 'finland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('571f4099-bb97-5a74-bdb0-1e858bd443bc', 'Finland Improving Corporate Governance of Unlisted Companies', 'Improving Corporate Governance of Unlisted Companies', 'On the basis of the proposals by the working group the Board of Directors of the Central Chamber of Commerce of Finland has issued An agenda for Improving Corporate Governance of Unlisted Companies, i.e. companies which are not considered able to implement the Corporate Governance Recommendation for Listed Companies, but which nevertheless desire to improve their operations in conformity with good corporate governance principles.', 'On the basis of the proposals by the working group the Board of Directors of the Central Chamber of Commerce of Finland has issued An agenda for Improving Corporate Governance of Unlisted Companies, i.e. companies which are not considered able to implement the Corporate Governance Recommendation for Listed Companies, but which nevertheless desire to improve their operations in conformity with good corporate governance principles.', 'On the basis of the proposals by the working group the Board of Directors of the Central Chamber of Commerce of Finland has issued An agenda for Improving Corporate Governance of Unlisted Companies, i.e. companies which are not considered able to implement the Corporate Governance Recommendation for Listed Companies, but which nevertheless desire to improve their operations in conformity with good corporate governance principles.', 'Finland', 'nature', 'in_force', '2006-01-01'::date, 'Finland', 'https://www.carrotsandsticks.org/policies/57_9', ARRAY['guidance_frameworks', 'other sustainability policy', 'mandatory', 'sdg16', 'sdg15', 'finland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('ea124df3-0255-57e6-97bd-264b334fb9eb', 'Finland Corporate Governance Recommendations for Listed Companies', 'Corporate Governance Recommendations for Listed Companies', 'HEX Plc, the Central Chamber of Commerce of Finland and the Confederation of Finnish Industry and Employers appointed a working group on 17 February 2003 to clarify the need of reviewing the corporate governance recommendation for listed companies issued by the Central Chamber of Commerce of Finland and the Confederation of Finnish Industry and Employers in 1997.', 'HEX Plc, the Central Chamber of Commerce of Finland and the Confederation of Finnish Industry and Employers appointed a working group on 17 February 2003 to clarify the need of reviewing the corporate governance recommendation for listed companies issued by the Central Chamber of Commerce of Finland and the Confederation of Finnish Industry and Employers in 1997.', 'HEX Plc, the Central Chamber of Commerce of Finland and the Confederation of Finnish Industry and Employers appointed a working group on 17 February 2003 to clarify the need of reviewing the corporate governance recommendation for listed companies issued by the Central Chamber of Commerce of Finland and the Confederation of Finnish Industry and Employers in 1997.', 'Finland', 'nature', 'in_force', '2003-01-01'::date, 'Finland', 'https://www.carrotsandsticks.org/policies/57_10', ARRAY['guidance_frameworks', 'voluntary', 'sdg16', 'sdg15', 'disclosure', 'sdg9', 'finland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('18addee7-8eb7-5748-b5ba-7474697733c9', 'Finland Recommendation on corporate governance systems for listed companies', 'Recommendation on corporate governance systems for listed companies', 'As the Finnish corporate governance system is based on mandatory legislation, this recommendation is designed to supplement statutory procedures. The aim of the recommendation is to harmonize the operating methods of listed companies, to improve the transparency of operations, to harmonize the information provided to investors and shareholders, and to improve the flow of information. This way you can add the interest of domestic and foreign investors in Finnish listed companies and promote confidence in the securities market.', 'As the Finnish corporate governance system is based on mandatory legislation, this recommendation is designed to supplement statutory procedures. The aim of the recommendation is to harmonize the operating methods of listed companies, to improve the transparency of operations, to harmonize the information provided to investors and shareholders, and to improve the flow of information. This way you can add the interest of domestic and foreign investors in Finnish listed companies and promote confidence in the securities market.', 'As the Finnish corporate governance system is based on mandatory legislation, this recommendation is designed to supplement statutory procedures. The aim of the recommendation is to harmonize the operating methods of listed companies, to improve the transparency of operations, to harmonize the information provided to investors and shareholders, and to improve the flow of information. This way you can add the interest of domestic and foreign investors in Finnish listed companies and promote confidence in the securities market.', 'Finland', 'governance', 'in_force', '2003-01-01'::date, 'Finland', 'https://www.carrotsandsticks.org/policies/57_27', ARRAY['finland', 'guidance_frameworks', 'sdg16', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2c30b7c1-a45a-552b-b69c-e0e8e3557d37', 'Finland Accounting Act', 'Accounting Act 1336/1997', 'The Finnish Accounting Act (1336/1997), as amended in 2016 by Act 2016/1376, requires large public interest entities to include material non-financial issues in their annual/financial reports from financial year 2017 onwards. This includes information on environmental matters, social and employee-related matters, respect for human rights, anti-corruption, and bribery. The amendment is intended to reflect the content in the European Commission Directive 2013/34/EU, which states that reporting information "should not be restricted to the financial aspects of the undertaking''s business, and there should be an analysis of environmental and social aspects of the business necessary for an understanding of the undertaking''s development, performance or position."', 'The Finnish Accounting Act (1336/1997), as amended in 2016 by Act 2016/1376, requires large public interest entities to include material non-financial issues in their annual/financial reports from financial year 2017 onwards. This includes information on environmental matters, social and employee-related matters, respect for human rights, anti-corruption, and bribery. The amendment is intended to reflect the content in the European Commission Directive 2013/34/EU, which states that reporting information "should not be restricted to the financial aspects of the undertaking''s business, and there should be an analysis of environmental and social aspects of the business necessary for an understanding of the undertaking''s development, performance or position."', 'The Finnish Accounting Act (1336/1997), as amended in 2016 by Act 2016/1376, requires large public interest entities to include material non-financial issues in their annual/financial reports from financial year 2017 onwards. This includes information on environmental matters, social and employee-related matters, respect for human rights, anti-corruption, and bribery. The amendment is intended to reflect the content in the European Commission Directive 2013/34/EU, which states that reporting information "should not be restricted to the financial aspects of the undertaking''s business, and there should be an analysis of environmental and social aspects of the business necessary for an understanding of the undertaking''s development, performance or position."', 'Finland', 'climate', 'in_force', '1997-01-01'::date, 'Finland', 'https://www.carrotsandsticks.org/policies/57_17', ARRAY['sdg8', 'regulations', 'mandatory', 'sdg16', 'disclosure', 'finland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e8a42b8b-c47e-5230-a364-95427732b3b3', 'Finland Accounting Act', 'Accounting Act 1336/1997', 'The Accounting Act 1336/1997 in Finland outlines the obligation for legal entities and natural persons, except farmers and fishers, to maintain accounting records following good accounting practices. It specifies thresholds for double-entry bookkeeping and financial statement preparation based on assets, turnover, and employee numbers. The Act categorizes entities as small, micro, or large undertakings based on financial criteria. It also addresses control criteria between reporting entities and foreign undertakings. The policy aims to ensure transparent financial reporting and compliance with international standards.', 'The Accounting Act 1336/1997 in Finland outlines the obligation for legal entities and natural persons, except farmers and fishers, to maintain accounting records following good accounting practices. It specifies thresholds for double-entry bookkeeping and financial statement preparation based on assets, turnover, and employee numbers. The Act categorizes entities as small, micro, or large undertakings based on financial criteria. It also addresses control criteria between reporting entities and foreign undertakings. The policy aims to ensure transparent financial reporting and compliance with international standards.', 'The Accounting Act 1336/1997 in Finland outlines the obligation for legal entities and natural persons, except farmers and fishers, to maintain accounting records following good accounting practices. It specifies thresholds for double-entry bookkeeping and financial statement preparation based on assets, turnover, and employee numbers. The Act categorizes entities as small, micro, or large undertakings based on financial criteria. It also addresses control criteria between reporting entities and foreign undertakings. The policy aims to ensure transparent financial reporting and compliance with international standards.', 'Finland', 'climate', 'in_force', '1997-01-01'::date, 'Finland', 'https://www.carrotsandsticks.org/policies/57_6', ARRAY['sdg8', 'other sustainability policy', 'regulations', 'mandatory', 'sdg15', 'finland']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('547c5364-464d-5ad9-94ef-d47b661e66d6', 'France DDADUE 2025 law (Law )', 'DDADUE 2025 law (Law No. 2025-391)', 'The DDADUE 2025 law (Law No. 2025-391) aims to adapt French law to align with European Union regulations concerning economic, financial, environmental, and energy matters. It includes provisions that modify the monetary and financial code, particularly regarding investment service providers and their fee structures. The law mandates compliance with EU directives and regulations, ensuring that financial institutions operate transparently and sustainably. It applies to all financial service providers in France and is considered mandatory for compliance with EU standards.', 'The DDADUE 2025 law (Law No. 2025-391) aims to adapt French law to align with European Union regulations concerning economic, financial, environmental, and energy matters. It includes provisions that modify the monetary and financial code, particularly regarding investment service providers and their fee structures. The law mandates compliance with EU directives and regulations, ensuring that financial institutions operate transparently and sustainably. It applies to all financial service providers in France and is considered mandatory for compliance with EU standards.', 'The DDADUE 2025 law (Law No. 2025-391) aims to adapt French law to align with European Union regulations concerning economic, financial, environmental, and energy matters. It includes provisions that modify the monetary and financial code, particularly regarding investment service providers and their fee structures. The law mandates compliance with EU directives and regulations, ensuring that financial institutions operate transparently and sustainably. It applies to all financial service providers in France and is considered mandatory for compliance with EU standards.', 'France', 'climate', 'in_force', '2025-01-01'::date, 'France', 'https://www.carrotsandsticks.org/policies/58_73', ARRAY['regulations', 'sdg7', 'mandatory', 'france', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('bf0e6d57-781a-53ce-a2cf-7513e7aa356e', 'France Decree of 31 January 2024 amending Decree', 'Decree No. 2024-60 of 31 January 2024 amending Decree No. 2023-1394 of 30 December 2023 issued pursuant to Ordinance No. 2023-1142 of 6 December 2023 relating to the publication and certification of sustainability information and the environmental, social and corporate governance obligations of commercial companies', 'Decree No. 2024-60 amends Decree No. 2023-1394 concerning sustainability information and corporate governance obligations for commercial companies in France. It modifies the implementation dates and targets auditors, accountants, and independent third-party organizations.', 'Decree No. 2024-60 amends Decree No. 2023-1394 concerning sustainability information and corporate governance obligations for commercial companies in France. It modifies the implementation dates and targets auditors, accountants, and independent third-party organizations.', 'Decree No. 2024-60 amends Decree No. 2023-1394 concerning sustainability information and corporate governance obligations for commercial companies in France. It modifies the implementation dates and targets auditors, accountants, and independent third-party organizations.', 'France', 'governance', 'in_force', '2024-01-01'::date, 'France', 'https://www.carrotsandsticks.org/policies/58_65', ARRAY['france', 'mandatory', 'sdg16', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('f2597cea-fa1d-5bc2-814a-97352fb8aaba', 'France Decree of 30 December 2023 issued pursuant', 'Decree No. 2023-1394 of 30 December 2023 issued pursuant to Ordinance No. 2023-1142 of 6 December 2023 relating to the publication and certification of sustainability information and the environmental, social and corporate governance obligations of commercial companies', 'Decree No. 2023-1394 in France enforces sustainability reporting and ESG obligations for commercial entities. It mandates specific disclosures, certifications, and governance adjustments in line with EU directives. Applicable to various commercial entities, auditors, and regulatory bodies, effective for financial years starting from January 1, 2024, with phased-in requirements until 2028.', 'Decree No. 2023-1394 in France enforces sustainability reporting and ESG obligations for commercial entities. It mandates specific disclosures, certifications, and governance adjustments in line with EU directives. Applicable to various commercial entities, auditors, and regulatory bodies, effective for financial years starting from January 1, 2024, with phased-in requirements until 2028.', 'Decree No. 2023-1394 in France enforces sustainability reporting and ESG obligations for commercial entities. It mandates specific disclosures, certifications, and governance adjustments in line with EU directives. Applicable to various commercial entities, auditors, and regulatory bodies, effective for financial years starting from January 1, 2024, with phased-in requirements until 2028.', 'France', 'climate', 'in_force', '2023-01-01'::date, 'France', 'https://www.carrotsandsticks.org/policies/58_66', ARRAY['france', 'mandatory', 'sdg16', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('29cb5c0a-7e42-543c-9aae-4d8bced89231', 'France Order of 28 December 2023 issued pursuant', 'Order of 28 December 2023 issued pursuant to Article 37 of Ordinance No. 2023-1142 of 6 December 2023 relating to the publication and certification of information on sustainability and the environmental, social and corporate governance obligations of commercial companies', 'The Order of 28 December 2023 in France mandates training for auditors and individuals in independent third-party organizations on sustainability reporting. It sets out qualifying activities, limits training hours to 30, and requires compliance by 1 January 2024.', 'The Order of 28 December 2023 in France mandates training for auditors and individuals in independent third-party organizations on sustainability reporting. It sets out qualifying activities, limits training hours to 30, and requires compliance by 1 January 2024.', 'The Order of 28 December 2023 in France mandates training for auditors and individuals in independent third-party organizations on sustainability reporting. It sets out qualifying activities, limits training hours to 30, and requires compliance by 1 January 2024.', 'France', 'climate', 'in_force', '2023-01-01'::date, 'France', 'https://www.carrotsandsticks.org/policies/58_67', ARRAY['sdg4', 'regulations', 'mandatory', 'france', 'sdg16']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('e1bb218b-0a7c-5e0a-a816-256c09e3b9fe', 'France Order of 28 December 2023 amending Title II', 'Order of 28 December 2023 amending Title II of Book VIII of the Commercial Code', 'The Order of 28 December 2023 amends the Commercial Code in France to comply with EU sustainability reporting directives. It introduces requirements for auditors and independent third-party organizations. The policy targets companies, aiming to enhance sustainability reporting and governance practices.', 'The Order of 28 December 2023 amends the Commercial Code in France to comply with EU sustainability reporting directives. It introduces requirements for auditors and independent third-party organizations. The policy targets companies, aiming to enhance sustainability reporting and governance practices.', 'The Order of 28 December 2023 amends the Commercial Code in France to comply with EU sustainability reporting directives. It introduces requirements for auditors and independent third-party organizations. The policy targets companies, aiming to enhance sustainability reporting and governance practices.', 'France', 'climate', 'in_force', '2023-01-01'::date, 'France', 'https://www.carrotsandsticks.org/policies/58_68', ARRAY['france', 'mandatory', 'sdg16', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('1543618f-8f29-5188-b84a-2562bc8af675', 'France Environmental Code', 'Environmental Code', 'Companies with more than 500 employees have to publish their scope 1 and 2 greenhouse gas emissions by 31 December 2012 at the latest, with an update at least every three years. The scope of the reporting requirements is also extended to the State- localities with a population in excess of 50,000 and other public entities with more than 250 employees, must establish greenhouse gas emissions inventories.', 'Companies with more than 500 employees have to publish their scope 1 and 2 greenhouse gas emissions by 31 December 2012 at the latest, with an update at least every three years. The scope of the reporting requirements is also extended to the State- localities with a population in excess of 50,000 and other public entities with more than 250 employees, must establish greenhouse gas emissions inventories.', 'Companies with more than 500 employees have to publish their scope 1 and 2 greenhouse gas emissions by 31 December 2012 at the latest, with an update at least every three years. The scope of the reporting requirements is also extended to the State- localities with a population in excess of 50,000 and other public entities with more than 250 employees, must establish greenhouse gas emissions inventories.', 'France', 'climate', 'in_force', '2022-01-01'::date, 'France', 'https://www.carrotsandsticks.org/policies/58_33', ARRAY['sdg2', 'sdg13', 'other sustainability policy', 'mandatory', 'france', 'mandatory_regulations', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7129bb20-68d4-5941-b0a7-f4634c2f6f4a', 'France Labour Code', 'Labour Code', 'The French Labour Code (Code du Travail) provides a comprehensive (perhaps too comprehensive – there are reforms under way to simplify it) framework for both individual and collective relationships between employers and employees.', 'The French Labour Code (Code du Travail) provides a comprehensive (perhaps too comprehensive – there are reforms under way to simplify it) framework for both individual and collective relationships between employers and employees.', 'The French Labour Code (Code du Travail) provides a comprehensive (perhaps too comprehensive – there are reforms under way to simplify it) framework for both individual and collective relationships between employers and employees.', 'France', 'social', 'in_force', '2022-01-01'::date, 'France', 'https://www.carrotsandsticks.org/policies/58_34', ARRAY['sdg8', 'other sustainability policy', 'mandatory', 'france', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('10873cac-8930-536a-a053-52c459248d12', 'France Energy Code', 'Energy Code', 'The Energy Code states that Electricité de France, the French state or other public-sector companies or entities must own together the majority of RTE’s capital (Article L. 111-42). On 1 April 2017, 49.9% of its capital was sold to the Caisse des dépôts et consignations, a French public financial entity, and CNP Assurances.', 'The Energy Code states that Electricité de France, the French state or other public-sector companies or entities must own together the majority of RTE’s capital (Article L. 111-42). On 1 April 2017, 49.9% of its capital was sold to the Caisse des dépôts et consignations, a French public financial entity, and CNP Assurances.', 'The Energy Code states that Electricité de France, the French state or other public-sector companies or entities must own together the majority of RTE’s capital (Article L. 111-42). On 1 April 2017, 49.9% of its capital was sold to the Caisse des dépôts et consignations, a French public financial entity, and CNP Assurances.', 'France', 'climate', 'in_force', '2022-01-01'::date, 'France', 'https://www.carrotsandsticks.org/policies/58_38', ARRAY['sdg13', 'sdg14', 'other sustainability policy', 'sdg7', 'sdg11', 'mandatory', 'france', 'mandatory_regulations', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('201444aa-3730-5675-ac45-8768510cb9ea', 'France Trade Code', 'Trade Code', 'The "Code de commerce" in France is a legal document that regulates commercial law, including the obligations of businesses. It outlines the legal requirements for conducting business in France, such as registration, taxation, and accounting. The code also covers consumer protection, competition law, and corporate governance. The obligations of businesses under the code include the requirement to keep accurate financial records, pay taxes and social security contributions, and comply with labor laws. Additionally, businesses are obligated to follow rules related to advertising, product safety, and data protection. The code establishes penalties for non-compliance with these obligations, such as fines and legal action.', 'The "Code de commerce" in France is a legal document that regulates commercial law, including the obligations of businesses. It outlines the legal requirements for conducting business in France, such as registration, taxation, and accounting. The code also covers consumer protection, competition law, and corporate governance. The obligations of businesses under the code include the requirement to keep accurate financial records, pay taxes and social security contributions, and comply with labor laws. Additionally, businesses are obligated to follow rules related to advertising, product safety, and data protection. The code establishes penalties for non-compliance with these obligations, such as fines and legal action.', 'The "Code de commerce" in France is a legal document that regulates commercial law, including the obligations of businesses. It outlines the legal requirements for conducting business in France, such as registration, taxation, and accounting. The code also covers consumer protection, competition law, and corporate governance. The obligations of businesses under the code include the requirement to keep accurate financial records, pay taxes and social security contributions, and comply with labor laws. Additionally, businesses are obligated to follow rules related to advertising, product safety, and data protection. The code establishes penalties for non-compliance with these obligations, such as fines and legal action.', 'France', 'climate', 'in_force', '2022-01-01'::date, 'France', 'https://www.carrotsandsticks.org/policies/58_55', ARRAY['other sustainability policy', 'regulations', 'sdg11', 'mandatory', 'france', 'sdg16', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('c3586844-0c88-5a11-ab12-3791f117b15c', 'France Decree of 29 April 2022 relating to consumer', 'Decree No. 2022-748 of 29 April 2022 relating to consumer information on the qualities and environmental characteristics of products that generate waste', 'France''s Decree No. 2022-748 mandates consumer information on environmental aspects of waste-generating products. Producers with over €10 million annual revenue and 10,000 units sold must disclose product sustainability, recyclability, and eco-features. Effective from 2023, this policy targets producers, importers, and distributors, enhancing consumer awareness and eco-friendly choices.', 'France''s Decree No. 2022-748 mandates consumer information on environmental aspects of waste-generating products. Producers with over €10 million annual revenue and 10,000 units sold must disclose product sustainability, recyclability, and eco-features. Effective from 2023, this policy targets producers, importers, and distributors, enhancing consumer awareness and eco-friendly choices.', 'France''s Decree No. 2022-748 mandates consumer information on environmental aspects of waste-generating products. Producers with over €10 million annual revenue and 10,000 units sold must disclose product sustainability, recyclability, and eco-features. Effective from 2023, this policy targets producers, importers, and distributors, enhancing consumer awareness and eco-friendly choices.', 'France', 'climate', 'in_force', '2022-01-01'::date, 'France', 'https://www.carrotsandsticks.org/policies/58_72', ARRAY['france', 'mandatory', 'sdg12', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('7e2fd8cb-3673-5d81-836c-a5b129b691bd', 'France Decree of May 27, 2021 taken in application', 'Decree No. 2021-663 of May 27, 2021 taken in application of Article L. 533-22-1 of the Monetary and Financial Code', 'Decree n° 2021-663 of May 27, 2021, operationalizes Article 29 of France’s Energy and Climate Law (2019) by enhancing transparency in climate and ESG reporting for financial institutions and corporations. It mandates detailed disclosures on climate and biodiversity risks, sustainability measures, and alignment with Paris Agreement goals. The decree applies to insurers, pension funds, asset managers, and credit institutions, requiring them to categorize financial disclosures by asset class, outline alignment strategies for 2030 and 2050, and report biodiversity impacts using standardized indicators.
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5539e897-3138-5cc0-961d-87178822357d', 'France Law of 24 December 2021 aimed at accelerating', 'Law No. 2021-1774 of 24 December 2021 aimed at accelerating economic and professional equality', 'The Law No. 2021-1774 in France aims to accelerate economic and professional equality by modifying various labor and financial codes. It addresses salary payment, bank account access, parental leave, and education statistics disclosure, with a focus on gender equality and workers'' rights. Targeted at improving equality and rights in the workplace and education sectors.', 'The Law No. 2021-1774 in France aims to accelerate economic and professional equality by modifying various labor and financial codes. It addresses salary payment, bank account access, parental leave, and education statistics disclosure, with a focus on gender equality and workers'' rights. Targeted at improving equality and rights in the workplace and education sectors.', 'The Law No. 2021-1774 in France aims to accelerate economic and professional equality by modifying various labor and financial codes. It addresses salary payment, bank account access, parental leave, and education statistics disclosure, with a focus on gender equality and workers'' rights. Targeted at improving equality and rights in the workplace and education sectors.', 'France', 'social', 'in_force', '2021-01-01'::date, 'France', 'https://www.carrotsandsticks.org/policies/58_70', ARRAY['sdg4', 'sdg8', 'regulations', 'mandatory', 'sdg5', 'france']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a6990954-2a79-50b5-be83-4ddbee4c4b31', 'France Governance and management of climate risks by banking', 'Governance and management of climate risks by banking institutions: some good practices', 'This document is a continuation of the ACPR''s work, begun in 2016, on the risks associated with climate change within the framework of provision V of law no. 2015-992 of August 17, 2015 relating to the transition energy for green growth.', 'This document is a continuation of the ACPR''s work, begun in 2016, on the risks associated with climate change within the framework of provision V of law no. 2015-992 of August 17, 2015 relating to the transition energy for green growth.', 'This document is a continuation of the ACPR''s work, begun in 2016, on the risks associated with climate change within the framework of provision V of law no. 2015-992 of August 17, 2015 relating to the transition energy for green growth.', 'France', 'climate', 'in_force', '2020-01-01'::date, 'France', 'https://www.carrotsandsticks.org/policies/58_24', ARRAY['sdg13', 'regulations', 'sdg7', 'mandatory', 'france', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('eac20931-81f4-511e-8be9-b29ddd497055', 'France fist assessment of financial risks stemming from climate', 'The fist assessment of financial risks stemming from climate change: The main results of the 2020 climate pilot exercise', 'This document outlines the main results of the 2020 climate pilot exercise conducted by the ACPR.', 'This document outlines the main results of the 2020 climate pilot exercise conducted by the ACPR.', 'This document outlines the main results of the 2020 climate pilot exercise conducted by the ACPR.', 'France', 'climate', 'in_force', '2020-01-01'::date, 'France', 'https://www.carrotsandsticks.org/policies/58_31', ARRAY['sdg13', 'other sustainability policy', 'mandatory', 'france', 'mandatory_regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('758441ad-8d4b-5e5d-a8e4-81f3737bacf5', 'France Corporate Governance Code of Listed Corporations', 'Corporate Governance Code of Listed Corporations 2020', 'This code presents the 2020 updated version of a set of recommendations that enables these companies to improve their functioning and management in an atmosphere of enhanced transparency and thus respond to the expectations of investors and the public.', 'This code presents the 2020 updated version of a set of recommendations that enables these companies to improve their functioning and management in an atmosphere of enhanced transparency and thus respond to the expectations of investors and the public.', 'This code presents the 2020 updated version of a set of recommendations that enables these companies to improve their functioning and management in an atmosphere of enhanced transparency and thus respond to the expectations of investors and the public.', 'France', 'governance', 'in_force', '2020-01-01'::date, 'France', 'https://www.carrotsandsticks.org/policies/58_64', ARRAY['guidance_frameworks', 'mandatory', 'france', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('83cc6e43-2194-59c9-90f9-cf05e1a26099', 'France Law of 10 February 2020 relating to the', 'Law No. 2020-105 of 10 February 2020 relating to the fight against waste and the circular economy (1)', 'Law No. 2020-105 of 10 February 2020 in France focuses on waste reduction and promoting a circular economy. It sets targets for eco-design, recycling rates, and phasing out single-use plastic packaging. Producers, waste handlers, and policymakers are key targets for compliance and implementation.', 'Law No. 2020-105 of 10 February 2020 in France focuses on waste reduction and promoting a circular economy. It sets targets for eco-design, recycling rates, and phasing out single-use plastic packaging. Producers, waste handlers, and policymakers are key targets for compliance and implementation.', 'Law No. 2020-105 of 10 February 2020 in France focuses on waste reduction and promoting a circular economy. It sets targets for eco-design, recycling rates, and phasing out single-use plastic packaging. Producers, waste handlers, and policymakers are key targets for compliance and implementation.', 'France', 'circularity', 'in_force', '2020-01-01'::date, 'France', 'https://www.carrotsandsticks.org/policies/58_71', ARRAY['france', 'mandatory', 'sdg12', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('824559dd-acf5-5144-aa77-7ca331f036ed', 'France Law n° 2019-486 of May 22, 2019', 'Law n° 2019-486 of May 22, 2019 relating to the growth and transformation of companies', 'This document outlines the law n° 2019-486 of May 22, 2019 relating to the growth and transformation of companies.', 'This document outlines the law n° 2019-486 of May 22, 2019 relating to the growth and transformation of companies.', 'This document outlines the law n° 2019-486 of May 22, 2019 relating to the growth and transformation of companies.', 'France', 'climate', 'in_force', '2019-01-01'::date, 'France', 'https://www.carrotsandsticks.org/policies/58_29', ARRAY['sdg2', 'sdg14', 'other sustainability policy', 'regulations', 'sdg11', 'mandatory', 'france', 'sdg15']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('5f2b097e-1752-560e-b9a8-17bdadb0ff0e', 'France Law n° 2019-1147 of November 8, 2019', 'Law n° 2019-1147 of November 8, 2019 relating to energy and climate', 'This document is concerned with the law n° 2019-1147 of November 8, 2019 relating to energy and climate.', 'This document is concerned with the law n° 2019-1147 of November 8, 2019 relating to energy and climate.', 'This document is concerned with the law n° 2019-1147 of November 8, 2019 relating to energy and climate.', 'France', 'climate', 'in_force', '2019-01-01'::date, 'France', 'https://www.carrotsandsticks.org/policies/58_54', ARRAY['sdg13', 'other sustainability policy', 'regulations', 'sdg7', 'sdg11', 'mandatory', 'france', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('132d59cd-73a9-5c30-9629-65d232e8d821', 'France Law n° 2019-1147 of November 8, 2019', 'Law n° 2019-1147 of November 8, 2019 relating to energy and climate', 'The French Energy and Climate Law, enacted on November 8, 2019, establishes an ambitious roadmap for achieving carbon neutrality by 2050. The legislation introduces mechanisms for significant reductions in greenhouse gas (GHG) emissions, the expansion of renewable energy, and the advancement of energy efficiency. Key objectives include a 40% reduction in fossil fuel use by 2030, increased investment in renewables, and the cessation of coal-fired power plant operations. Additionally, the law reinforces financial transparency by mandating climate risk disclosures from corporations and financial institutions.
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('a06af3f9-e713-55a7-be6b-105b0c29e437', 'Climate Energy Contribution in France: operation, income and exemptions', 'The Climate Energy Contribution in France: operation, income and exemptions', 'The Climate Energy Contribution policy in France aims to levy taxes on energy products based on their CO2 content to reduce emissions. It has evolved from a carbon tax to a climate energy contribution, with revenue used for renewable energy financing. The policy includes numerous exemptions but aims to reduce them gradually. The trajectory of the contribution has increased over the years, with set prices and targets. The policy supports national objectives of reducing greenhouse gas emissions and is backed by the Law on energy transition for green growth. Differential treatment is allowed if it serves the general interest.', 'The Climate Energy Contribution policy in France aims to levy taxes on energy products based on their CO2 content to reduce emissions. It has evolved from a carbon tax to a climate energy contribution, with revenue used for renewable energy financing. The policy includes numerous exemptions but aims to reduce them gradually. The trajectory of the contribution has increased over the years, with set prices and targets. The policy supports national objectives of reducing greenhouse gas emissions and is backed by the Law on energy transition for green growth. Differential treatment is allowed if it serves the general interest.', 'The Climate Energy Contribution policy in France aims to levy taxes on energy products based on their CO2 content to reduce emissions. It has evolved from a carbon tax to a climate energy contribution, with revenue used for renewable energy financing. The policy includes numerous exemptions but aims to reduce them gradually. The trajectory of the contribution has increased over the years, with set prices and targets. The policy supports national objectives of reducing greenhouse gas emissions and is backed by the Law on energy transition for green growth. Differential treatment is allowed if it serves the general interest.', 'France', 'climate', 'in_force', '2018-01-01'::date, 'France', 'https://www.carrotsandsticks.org/policies/58_25', ARRAY['sdg13', 'other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'france', 'sdg9']::text[]) ON CONFLICT (id) DO NOTHING;
