INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('4ee57de1-da57-5073-aa06-47f609966bc0', 'France Methodology Guide for Emissions Greenhouse Gas Greenhouse Water', 'Methodology Guide for Emissions Greenhouse Gas Greenhouse Water Services and Sanitation', 'This guide describes the calculations and the new emission factors specific to the Water and Sanitation businesses to be used for the assessment of each emitting item.', 'This guide describes the calculations and the new emission factors specific to the Water and Sanitation businesses to be used for the assessment of each emitting item.', 'This guide describes the calculations and the new emission factors specific to the Water and Sanitation businesses to be used for the assessment of each emitting item.', 'France', 'climate', 'in_force', '2018-01-01'::date, 'France', 'https://www.carrotsandsticks.org/policies/58_49', ARRAY['sdg13', 'other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'sdg6', 'france']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('3ba20389-c812-58da-a39b-6757a0ce9d99', 'France Corporate Governance Code of Listed Corporations', 'Corporate Governance Code of Listed Corporations 2018', 'This code presents the 2018 updated version of a set of recommendations that enables these companies to improve their functioning and management in an atmosphere of enhanced transparency and thus respond to the expectations of investors and the public.', 'This code presents the 2018 updated version of a set of recommendations that enables these companies to improve their functioning and management in an atmosphere of enhanced transparency and thus respond to the expectations of investors and the public.', 'This code presents the 2018 updated version of a set of recommendations that enables these companies to improve their functioning and management in an atmosphere of enhanced transparency and thus respond to the expectations of investors and the public.', 'France', 'governance', 'in_force', '2018-01-01'::date, 'France', 'https://www.carrotsandsticks.org/policies/58_63', ARRAY['guidance_frameworks', 'mandatory', 'france', 'sdg16', 'disclosure']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('74976a27-0ca3-5e7e-ae10-9e85a18c2e60', 'France LAW of March 27, 2017 relating to the', 'LAW No. 2017-399 of March 27, 2017 relating to the duty of vigilance of parent companies and ordering companies', 'This document outlines the French Law relating to the duty of vigilance of parent companies and ordering companies.', 'This document outlines the French Law relating to the duty of vigilance of parent companies and ordering companies.', 'This document outlines the French Law relating to the duty of vigilance of parent companies and ordering companies.', 'France', 'governance', 'in_force', '2017-01-01'::date, 'France', 'https://www.carrotsandsticks.org/policies/58_5', ARRAY['france', 'mandatory', 'other sustainability policy', 'regulations']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('6647b66b-bcae-5625-b596-c59d0e8dff44', 'France Law n° 2016-138 of February 11, 2016', 'Law n° 2016-138 of February 11, 2016 relating to the fight against food waste', 'The French Law n° 2016-138 of February 11, 2016, aims to combat food waste by promoting the use of unsold items for human consumption, animal feed, compost, and energy recovery. It emphasizes awareness-raising, training, and mobilization of producers, processors, distributors, consumers, and associations. The law prohibits making unsold edible food unfit for consumption and mandates food sector operators to donate unsold food to authorized charities. Non-compliance incurs fines. The policy enforces a hierarchy for food recovery actions and sets guidelines for marketing and donation agreements, promoting a circular economy approach in the food sector.', 'The French Law n° 2016-138 of February 11, 2016, aims to combat food waste by promoting the use of unsold items for human consumption, animal feed, compost, and energy recovery. It emphasizes awareness-raising, training, and mobilization of producers, processors, distributors, consumers, and associations. The law prohibits making unsold edible food unfit for consumption and mandates food sector operators to donate unsold food to authorized charities. Non-compliance incurs fines. The policy enforces a hierarchy for food recovery actions and sets guidelines for marketing and donation agreements, promoting a circular economy approach in the food sector.', 'The French Law n° 2016-138 of February 11, 2016, aims to combat food waste by promoting the use of unsold items for human consumption, animal feed, compost, and energy recovery. It emphasizes awareness-raising, training, and mobilization of producers, processors, distributors, consumers, and associations. The law prohibits making unsold edible food unfit for consumption and mandates food sector operators to donate unsold food to authorized charities. Non-compliance incurs fines. The policy enforces a hierarchy for food recovery actions and sets guidelines for marketing and donation agreements, promoting a circular economy approach in the food sector.', 'France', 'climate', 'in_force', '2016-01-01'::date, 'France', 'https://www.carrotsandsticks.org/policies/58_1', ARRAY['sdg4', 'sdg2', 'other sustainability policy', 'regulations', 'sdg7', 'mandatory', 'france', 'sdg12']::text[]) ON CONFLICT (id) DO NOTHING;
