INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('d4e9253e-85f3-590f-bdbc-3ae49db29f4e', 'France Application Guide to the AFEP-MEDEF Corporate Governance Code', 'Application Guide to the AFEP-MEDEF Corporate Governance Code for Listed Companies of November 2016', 'The purpose of this guide is to clarify the interpretation adopted by the High Committee for Corporate Governance (HCGE) for certain recommendations of the Afep Medef corporate governance code for listed companies and to provide tools to facilitate its application.', 'The purpose of this guide is to clarify the interpretation adopted by the High Committee for Corporate Governance (HCGE) for certain recommendations of the Afep Medef corporate governance code for listed companies and to provide tools to facilitate its application.', 'The purpose of this guide is to clarify the interpretation adopted by the High Committee for Corporate Governance (HCGE) for certain recommendations of the Afep Medef corporate governance code for listed companies and to provide tools to facilitate its application.', 'France', 'climate', 'in_force', '2016-01-01'::date, 'France', 'https://www.carrotsandsticks.org/policies/58_13', ARRAY['guidance_frameworks', 'other sustainability policy', 'mandatory', 'sdg16', 'france']::text[]) ON CONFLICT (id) DO NOTHING;
INSERT INTO regulations (id, title, formal_title, summary, description, full_description, region, category, status, effective_date, source_name, source_url, tags) VALUES ('2d2d0e4d-1b45-5a60-a9a5-021895c86a37', 'France National Action Plan for the Implementation of the', 'National Action Plan for the Implementation of the United Nations Guiding Principles on Business and Human Rights 2016', 'This action plan shows that human rights are central to France''s actions supporting the promotion and development of CSR at the European and international levels.', 'This action plan shows that human rights are central to France''s actions supporting the promotion and development of CSR at the European and international levels.', 'This action plan shows that human rights are central to France''s actions supporting the promotion and development of CSR at the European and international levels.', 'France', 'climate', 'in_force', '2016-01-01'::date, 'France', 'https://www.carrotsandsticks.org/policies/58_23', ARRAY['regulations', 'sdg16', 'france', 'disclosure', 'voluntary']::text[]) ON CONFLICT (id) DO NOTHING;
